begin;
\ir fixtures/clinical.sql
select pg_temp.command('create',jsonb_build_object('patient_id',pg_temp.patient(),'snapshot',pg_temp.snapshot()),8001);
select pg_temp.put('order',jsonb_build_object('id',pg_temp.id(8500),'kind','lab','request','Synthetic authored lab request','due_at',null,'state','requested','reason',''));
select pg_temp.command('save',jsonb_build_object('snapshot',jsonb_set(pg_temp.snapshot(),'{orders}',jsonb_build_array(pg_temp.v('order')))),8002);
create function pg_temp.fi()returns jsonb language sql as $$select jsonb_build_object('encounter_id',pg_temp.v('encounter')->>'encounter_id','source_version_id',pg_temp.detail()->'versions'->0->>'id','order_id',pg_temp.id(8500),'source_ref','Synthetic operational source')$$;
create function pg_temp.fc(action text,n integer,ver integer,k integer,input jsonb)returns jsonb language sql as $$select public.doctor_fulfillment_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(n),ver,action,input,pg_temp.id(k))$$;
select throws_ok($$select pg_temp.fc('create',8600,0,8601,pg_temp.fi())$$,'42501','DOCTOR_FULFILLMENT_REQUEST_DENIED','draft clinical request cannot become issued operational work');
select pg_temp.command('start','{}',8003);
select pg_temp.command('finalize','{}',8004);
select is(pg_temp.fc('create',8600,0,8602,pg_temp.fi())->>'state','requested','C01: exact issued order creates operational record');
select is(pg_temp.fc('create',8600,0,8602,pg_temp.fi())->>'version','1','exact create retry does not duplicate event');
select throws_ok($$select pg_temp.fc('create',8601,0,8603,pg_temp.fi())$$,'40001','DOCTOR_FULFILLMENT_CONFLICT','same order cannot create a second fulfillment');
select is(pg_temp.fc('arrange',8600,1,8604,'{"source_ref":"Synthetic manual arrangement"}')->>'state','arranged','staff administrative arrangement does not send to partner');
select throws_ok($$select pg_temp.fc('receive',8600,2,8605,'{"source_ref":"Synthetic source","document_version_id":"d2020000-0000-4000-8000-000000009999","source_at":"2026-01-01T10:00:00Z","received_at":"2026-01-02T10:00:00Z"}')$$,'42501','DOCTOR_FULFILLMENT_DOCUMENT_DENIED','C02: unmatched file rejected');
select pg_temp.put('other_patient',public.doctor_write_patient(p_practice=>pg_temp.practice(),p_location=>pg_temp.location(),p_input=>'{"name":"Synthetic other fulfillment patient","phone":"","email":"","date_of_birth":null}',p_key=>pg_temp.id(8790)));
set local role service_role;
select pg_temp.put('wrong_upload',public.doctor_reserve_document(pg_temp.id(1),pg_temp.id(11),pg_temp.practice(),pg_temp.location(),(pg_temp.v('other_patient')->>'patient_id')::uuid,'synthetic-other.pdf','application/pdf',128,repeat('d',64),pg_temp.id(8791)));
select pg_temp.put('wrong_file',public.doctor_finalize_document(pg_temp.id(1),pg_temp.id(11),(pg_temp.v('wrong_upload')->>'intent_id')::uuid));
select pg_temp.put('upload',public.doctor_reserve_document(pg_temp.id(1),pg_temp.id(11),pg_temp.practice(),pg_temp.location(),pg_temp.patient(),'synthetic-fulfillment.pdf','application/pdf',128,repeat('c',64),pg_temp.id(8700)));
select pg_temp.put('file',public.doctor_finalize_document(pg_temp.id(1),pg_temp.id(11),(pg_temp.v('upload')->>'intent_id')::uuid));
set local role authenticated;select pg_temp.claim(1);
select pg_temp.put('receive_input',jsonb_build_object('source_ref','Synthetic outside source','document_version_id',pg_temp.v('file')->>'version_id','source_at','2026-01-01T10:00:00Z','received_at','2026-01-02T10:00:00Z'));
select throws_ok($$select pg_temp.fc('receive',8600,2,8792,pg_temp.v('receive_input')||jsonb_build_object('document_version_id',pg_temp.v('wrong_file')->>'version_id'))$$,'42501','DOCTOR_FULFILLMENT_DOCUMENT_DENIED','actual same-practice wrong-patient document is rejected');
select throws_ok($$select pg_temp.fc('receive',8600,2,8793,pg_temp.v('receive_input')||'{"source_at":"2026-01-03T10:00:00Z"}')$$,'22023','DOCTOR_FULFILLMENT_INVALID','source time cannot follow recorded receipt time');
select throws_ok($$select pg_temp.fc('receive',8600,2,8794,pg_temp.v('receive_input')||'{"clinical_review":true}')$$,'22023','DOCTOR_CONTACT_INVALID','operational input cannot promote clinical review');
select is(pg_temp.fc('receive',8600,2,8606,pg_temp.v('receive_input'))->>'state','received','C02: exact document records operational receipt');
select throws_ok($$select pg_temp.fc('receive',8600,2,8792,pg_temp.v('receive_input')||jsonb_build_object('document_version_id',pg_temp.v('wrong_file')->>'version_id'))$$,'42501','DOCTOR_FULFILLMENT_DOCUMENT_DENIED','actual same-practice wrong-patient document is rejected');
select throws_ok($$select pg_temp.fc('receive',8600,2,8793,pg_temp.v('receive_input')||'{"source_at":"2026-01-03T10:00:00Z"}')$$,'22023','DOCTOR_FULFILLMENT_INVALID','source time cannot follow recorded receipt time');
select throws_ok($$select pg_temp.fc('receive',8600,2,8794,pg_temp.v('receive_input')||'{"clinical_review":true}')$$,'22023','DOCTOR_CONTACT_INVALID','operational input cannot promote clinical review');
select is(pg_temp.fc('receive',8600,2,8606,pg_temp.v('receive_input'))->>'version','3','receipt retry preserves one event');
select is(public.doctor_fulfillments(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0)#>>'{rows,0,documents,0,review_state}','unreviewed','C03: operational receipt never marks clinical review');
select is(pg_temp.detail()->'versions'->0->'snapshot'->'results','[]'::jsonb,'M2 clinical snapshot is unchanged');
select ok(public.doctor_fulfillments(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0)::text not like '%Synthetic authored lab request%','administrative view omits clinical request text');
select throws_ok($$select pg_temp.fc('arrange',8600,3,8607,'{"source_ref":"Synthetic stale action"}')$$,'40001','DOCTOR_FULFILLMENT_CONFLICT','received record cannot silently reopen');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_fulfillments(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0)$$,'42501','DOCTOR_ACCESS_DENIED','foreign doctor denied');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.fc('cancel',8600,3,8608,'{"source_ref":"Synthetic denied"}')$$,'42501','DOCTOR_ACCESS_DENIED','read-only secretary cannot mutate');
select is(public.doctor_fulfillments(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0)#>'{rows,0,documents}','[]'::jsonb,'patients-only reader cannot see document version metadata');
select throws_ok($$select * from public.operational_fulfillments$$,'42501',null,'direct table access denied');
reset role;
select is((select count(*)::integer from public.operational_fulfillment_events where fulfillment_id=pg_temp.id(8600)),3,'duplicate reception preserves one event per version');
select is((select count(*)::integer from public.operational_fulfillment_documents where fulfillment_id=pg_temp.id(8600)),1,'exact document link is unique');
select * from finish();rollback;
